-- Save MJ: Queries (core SP call only)
DECLARE @ID_12406d2d765b UNIQUEIDENTIFIER,
@Name_12406d2d765b NVARCHAR(255),
@CategoryID_12406d2d765b UNIQUEIDENTIFIER,
@UserQuestion_12406d2d765b NVARCHAR(MAX),
@Description_12406d2d765b NVARCHAR(MAX),
@SQL_12406d2d765b NVARCHAR(MAX),
@TechnicalDescription_12406d2d765b NVARCHAR(MAX),
@OriginalSQL_12406d2d765b NVARCHAR(MAX),
@Feedback_12406d2d765b NVARCHAR(MAX),
@Status_12406d2d765b NVARCHAR(15),
@QualityRank_12406d2d765b INT,
@ExecutionCostRank_12406d2d765b INT,
@UsesTemplate_12406d2d765b BIT,
@AuditQueryRuns_12406d2d765b BIT,
@CacheEnabled_12406d2d765b BIT,
@CacheTTLMinutes_12406d2d765b INT,
@CacheMaxSize_12406d2d765b INT,
@EmbeddingVector_12406d2d765b NVARCHAR(MAX),
@EmbeddingModelID_12406d2d765b UNIQUEIDENTIFIER,
@CacheValidationSQL_12406d2d765b NVARCHAR(MAX),
@SQLDialectID_12406d2d765b UNIQUEIDENTIFIER,
@Reusable_12406d2d765b BIT,
@ExternalDataSourceID_12406d2d765b UNIQUEIDENTIFIER,
@IsMaterialized_12406d2d765b BIT
SET
  @ID_12406d2d765b = '6607C386-8978-44AF-96E4-7C78FEF848A4'
SET
  @Name_12406d2d765b = N'Party Customer Roster'
SET
  @CategoryID_12406d2d765b = '6C0A1000-0000-4000-A000-000000000002'
SET
  @UserQuestion_12406d2d765b = N'Which organizations and people have placed orders, how many, and when did they last order?'
SET
  @Description_12406d2d765b = N'Orders'' contribution to the Party Signals roster: one row per bill-to organization and one per bill-to person over non-voided orders, with the count and the latest order date. Read by the shared party pickers so a picker can offer customers before the rest of the directory. [signal: order|orders]'
SET
  @SQL_12406d2d765b = N'-- Orders'' contribution to the Party Signals roster.
--
-- Contract columns, in this order and under these names: PartyKind, PartyID, Count,
-- LastActivityAt. The shared party pickers union this with every other app''s signal query
-- to answer "is this party a customer" without knowing what an order is.
--
-- BILL-TO IS THE CUSTOMER (D65). Ship-to is where the goods land — a warehouse, a venue, an
-- attendee — and naming it here would offer a party we have never billed as a customer, which
-- is the confusion this query exists to remove.
--
-- Voided orders do not count: a voided order is a transaction that did not happen, and letting
-- one stand in for a customer relationship is how a mistyped party keeps looking like a real one.
-- No parameters; the picker filters client side.
SELECT
    N''organization'' AS PartyKind,
    h.BillToOrganizationID AS PartyID,
    COUNT(*) AS [Count],
    MAX(h.OrderDate) AS LastActivityAt
FROM [${flyway:defaultSchema}].vwOrderHeaders h
WHERE h.Status <> N''Voided''
  AND h.BillToOrganizationID IS NOT NULL
GROUP BY h.BillToOrganizationID

UNION ALL

SELECT
    N''person'' AS PartyKind,
    h.BillToPersonID AS PartyID,
    COUNT(*) AS [Count],
    MAX(h.OrderDate) AS LastActivityAt
FROM [${flyway:defaultSchema}].vwOrderHeaders h
WHERE h.Status <> N''Voided''
  AND h.BillToPersonID IS NOT NULL
GROUP BY h.BillToPersonID;
'
SET
  @TechnicalDescription_12406d2d765b = N'Party Signals contract columns PartyKind (''organization'' | ''person''), PartyID, Count, LastActivityAt. Two grouped selects over __mj_BizAppsOrders.vwOrderHeaders WHERE Status <> ''Voided'', unioned; bill-to is the customer (D65), ship-to is not. No parameters and no template — the picker filters and ranks the rows.'
SET
  @Status_12406d2d765b = N'Approved'
SET
  @QualityRank_12406d2d765b = 8
SET
  @ExecutionCostRank_12406d2d765b = 2
SET
  @UsesTemplate_12406d2d765b = 0
SET
  @AuditQueryRuns_12406d2d765b = 0
SET
  @CacheEnabled_12406d2d765b = 0
